`timescale 1ns/1ps
module radix2_div(
    input  wire        clk,
    input  wire        rst,
    input  wire [7:0]  dividend,
    input  wire [7:0]  divisor,
    input  wire        sign,
    input  wire        opn_valid,
    output reg         res_valid,
    input  wire        res_ready,
    output wire [15:0] result
);
    localparam IDLE = 2'd0, CALC = 2'd1, DONE = 2'd2;

    reg [1:0] state;
    reg [3:0] cnt;
    reg [8:0] R;
    reg [7:0] Q;
    reg [7:0] div_r;
    reg       q_sign;
    reg       r_sign;

    wire [8:0] R_shift = {R[7:0], Q[7]};
    wire [8:0] sub     = R_shift - {1'b0, div_r};
    wire       ge      = ~sub[8];

    wire [7:0] rem_u  = R[7:0];
    wire [7:0] quot_u = Q;
    wire [7:0] rem_out  = r_sign ? (~rem_u  + 8'd1) : rem_u;
    wire [7:0] quot_out = q_sign ? (~quot_u + 8'd1) : quot_u;
    assign result = {rem_out, quot_out};

    always @(posedge clk) begin
        if (rst) begin
            state     <= IDLE;
            res_valid <= 1'b0;
            cnt       <= 4'd0;
            R         <= 9'd0;
            Q         <= 8'd0;
            div_r     <= 8'd0;
            q_sign    <= 1'b0;
            r_sign    <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (opn_valid && !res_valid) begin
                        R      <= 9'd0;
                        Q      <= (sign & dividend[7]) ? (~dividend + 8'd1) : dividend;
                        div_r  <= (sign & divisor[7])  ? (~divisor  + 8'd1) : divisor;
                        q_sign <= sign & (dividend[7] ^ divisor[7]);
                        r_sign <= sign & dividend[7];
                        cnt    <= 4'd0;
                        state  <= CALC;
                    end
                end
                CALC: begin
                    R   <= ge ? sub : R_shift;
                    Q   <= {Q[6:0], ge};
                    cnt <= cnt + 4'd1;
                    if (cnt == 4'd7) state <= DONE;
                end
                DONE: begin
                    res_valid <= 1'b1;
                    if (res_valid && res_ready) begin
                        res_valid <= 1'b0;
                        state     <= IDLE;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

`timescale 1ns/1ps
module radix2_div(
    input  wire        clk,
    input  wire        rst,
    input  wire [7:0]  dividend,
    input  wire [7:0]  divisor,
    input  wire        sign,
    input  wire        opn_valid,
    output reg         res_valid,
    input  wire        res_ready,
    output wire [15:0] result
);
    // Single 16-bit shift register holds {R[15:8], Q[7:0]}.
    reg [15:0] sr;
    reg [7:0]  divisor_r;
    reg [3:0]  step;
    reg        busy;
    reg        q_sign;
    reg        r_sign;

    // Shift SR left by 1, then trial-subtract upper byte against |divisor|.
    wire [15:0] shifted = {sr[14:0], 1'b0};
    wire [8:0]  trial   = {1'b0, shifted[15:8]} - {1'b0, divisor_r};
    wire        take    = ~trial[8];
    wire [15:0] sr_next = {take ? trial[7:0] : shifted[15:8],
                           shifted[7:1],
                           take};

    wire [7:0] rem_u  = sr[15:8];
    wire [7:0] quot_u = sr[7:0];
    wire [7:0] rem_s  = r_sign ? (~rem_u  + 8'd1) : rem_u;
    wire [7:0] quot_s = q_sign ? (~quot_u + 8'd1) : quot_u;
    assign result = {rem_s, quot_s};

    always @(posedge clk) begin
        if (rst) begin
            sr        <= 16'd0;
            divisor_r <= 8'd0;
            step      <= 4'd0;
            busy      <= 1'b0;
            q_sign    <= 1'b0;
            r_sign    <= 1'b0;
            res_valid <= 1'b0;
        end else begin
            if (res_valid && res_ready) begin
                res_valid <= 1'b0;
            end
            if (!busy && !res_valid && opn_valid) begin
                sr        <= {8'd0, (sign & dividend[7]) ? (~dividend + 8'd1) : dividend};
                divisor_r <= (sign & divisor[7]) ? (~divisor + 8'd1) : divisor;
                q_sign    <= sign & (dividend[7] ^ divisor[7]);
                r_sign    <= sign & dividend[7];
                step      <= 4'd0;
                busy      <= 1'b1;
            end else if (busy) begin
                sr   <= sr_next;
                step <= step + 4'd1;
                if (step == 4'd7) begin
                    busy      <= 1'b0;
                    res_valid <= 1'b1;
                end
            end
        end
    end
endmodule

`timescale 1ns/1ps
module radix2_div(
    input  wire        clk,
    input  wire        rst,
    input  wire [7:0]  dividend,
    input  wire [7:0]  divisor,
    input  wire        sign,
    input  wire        opn_valid,
    output reg         res_valid,
    input  wire        res_ready,
    output wire [15:0] result
);
    // Non-restoring division with 10-bit signed partial remainder.
    // 10-bit range [-512, 511] safely holds 2*R + 1 for |R| < D <= 255.
    reg signed [9:0] R;
    reg        [7:0] Q;
    reg        [7:0] D;
    reg        [3:0] step;   // counts 0..8 (step 8 = finalize)
    reg              busy;
    reg              sq, sr;

    wire signed [9:0] D_ext   = {2'b00, D};
    wire signed [9:0] R_shift = {R[8:0], Q[7]};
    wire signed [9:0] R_next  = R[9] ? (R_shift + D_ext) : (R_shift - D_ext);
    wire              qbit    = ~R_next[9];
    wire signed [9:0] R_fix   = R[9] ? (R + D_ext) : R;  // final restore when R<0

    wire [7:0] rem_u  = R_fix[7:0];
    wire [7:0] quot_u = Q;
    wire [7:0] rem_o  = sr ? (~rem_u  + 8'd1) : rem_u;
    wire [7:0] quot_o = sq ? (~quot_u + 8'd1) : quot_u;
    assign result = {rem_o, quot_o};

    always @(posedge clk) begin
        if (rst) begin
            R         <= 10'sd0;
            Q         <= 8'd0;
            D         <= 8'd0;
            step      <= 4'd0;
            busy      <= 1'b0;
            sq        <= 1'b0;
            sr        <= 1'b0;
            res_valid <= 1'b0;
        end else begin
            if (res_valid && res_ready) res_valid <= 1'b0;

            if (!busy && !res_valid && opn_valid) begin
                R    <= 10'sd0;
                Q    <= (sign & dividend[7]) ? (~dividend + 8'd1) : dividend;
                D    <= (sign & divisor[7])  ? (~divisor  + 8'd1) : divisor;
                sq   <= sign & (dividend[7] ^ divisor[7]);
                sr   <= sign & dividend[7];
                step <= 4'd0;
                busy <= 1'b1;
            end else if (busy) begin
                if (step == 4'd8) begin
                    busy      <= 1'b0;
                    res_valid <= 1'b1;
                end else begin
                    R    <= R_next;
                    Q    <= {Q[6:0], qbit};
                    step <= step + 4'd1;
                end
            end
        end
    end
endmodule

`timescale 1ns/1ps
module radix2_div(
    input  wire        clk,
    input  wire        rst,
    input  wire [7:0]  dividend,
    input  wire [7:0]  divisor,
    input  wire        sign,
    input  wire        opn_valid,
    output reg         res_valid,
    input  wire        res_ready,
    output reg  [15:0] result
);
    // Fully unrolled 8-stage combinational divider. Trades area for latency:
    // one clock from opn_valid to res_valid (vs. 8 clocks for iterative styles).
    wire [7:0] abs_dividend = (sign & dividend[7]) ? (~dividend + 8'd1) : dividend;
    wire [7:0] abs_divisor  = (sign & divisor[7])  ? (~divisor  + 8'd1) : divisor;
    wire       qsgn         = sign & (dividend[7] ^ divisor[7]);
    wire       rsgn         = sign & dividend[7];

    // 9-iteration chain: lvl[0] = {R=0, Q=|dividend|}; lvl[8] = final {R,Q}.
    wire [15:0] lvl [0:8];
    assign lvl[0] = {8'd0, abs_dividend};

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : stage
            wire [15:0] sh   = {lvl[i][14:0], 1'b0};
            wire [8:0]  sub  = {1'b0, sh[15:8]} - {1'b0, abs_divisor};
            wire        ge   = ~sub[8];
            assign lvl[i+1] = {ge ? sub[7:0] : sh[15:8], sh[7:1], ge};
        end
    endgenerate

    wire [7:0] rem_u  = lvl[8][15:8];
    wire [7:0] quot_u = lvl[8][ 7:0];
    wire [7:0] rem_c  = rsgn ? (~rem_u  + 8'd1) : rem_u;
    wire [7:0] quot_c = qsgn ? (~quot_u + 8'd1) : quot_u;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 1'b0;
            result    <= 16'd0;
        end else begin
            if (res_valid && res_ready) res_valid <= 1'b0;
            if (!res_valid && opn_valid) begin
                result    <= {rem_c, quot_c};
                res_valid <= 1'b1;
            end
        end
    end
endmodule
